// Joins every migration in supabase/migrations/ into one file, in order, wrapped in a single transaction, for
// pasting into Supabase's SQL Editor in one go. Run after adding a migration: node scripts/bundle-migrations.mjs
import fs from 'node:fs';
import path from 'node:path';
const dir = path.join(import.meta.dirname, '..', 'supabase', 'migrations');
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();
const out = [
  '-- VieMo: every database migration in one file, in order. Generated by scripts/bundle-migrations.mjs; don\'t edit by hand.',
  '-- For a NEW, empty Supabase project: paste all of it into SQL Editor → New query, and press Run.',
  '-- It runs as one transaction: if anything fails, nothing is changed. Supabase will warn about "destructive',
  '-- operations": that is expected (the file revokes default permissions and defines functions that delete rows later).',
  '-- If some migrations have already run, use the individual files in supabase/migrations/ instead.',
  `-- Includes: ${files.join(', ')}`,
  '',
  'begin;',
  ...files.flatMap((f) => ['', `-- ==================== ${f} ====================`, fs.readFileSync(path.join(dir, f), 'utf8').trim()]),
  '',
  "notify pgrst, 'reload schema';",
  'commit;',
  '',
].join('\n');
fs.writeFileSync(path.join(dir, '..', 'setup-all-migrations.sql'), out);
console.log(`wrote supabase/setup-all-migrations.sql (${files.length} migrations, ${Math.round(out.length / 1024)} KB)`);
